def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.strip() + "\n", encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def update_query_package() -> None:
    QUERY_PACKAGE.parent.mkdir(parents=True, exist_ok=True)
    existing = (
        QUERY_PACKAGE.read_text(encoding="utf-8")
        if QUERY_PACKAGE.exists()
        else ""
    )
    lines = existing.splitlines()

    if UNIQUE_052_EXPORT not in lines:
        lines.append(UNIQUE_052_EXPORT)

    QUERY_PACKAGE.write_text(
        "\n".join(lines).rstrip() + "\n",
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] PACKAGE UPDATED: {QUERY_PACKAGE.resolve()}")


def verify_sources() -> None:
    ast.parse(INT_OIA_049_SOURCE, filename=str(INT_OIA_049_PRODUCTION))
    ast.parse(INT_OIA_052_SOURCE, filename=str(INT_OIA_052_PRODUCTION))
    ast.parse(INT_OIA_052_TEST_SOURCE, filename=str(INT_OIA_052_TEST))

    if 'SCHEMA_VERSION = "INT-OIA-049"' not in INT_OIA_049_SOURCE:
        raise RuntimeError("embedded INT-OIA-049 source contract mismatch")
    if 'SCHEMA_VERSION = "INT-OIA-052"' not in INT_OIA_052_SOURCE:
        raise RuntimeError("embedded INT-OIA-052 source contract mismatch")
    if (
        "consumption_attestation_authorization_secondary_consumption_gate"
        not in INT_OIA_052_TEST_SOURCE
    ):
        raise RuntimeError("corrected INT-OIA-052 test import is missing")

    print("[OK] Embedded INT-OIA-049 and INT-OIA-052 contracts verified")


def run_test(path: Path) -> None:
    if not path.exists():
        raise FileNotFoundError(f"required test missing: {path}")
    completed = subprocess.run(
        [sys.executable, str(path)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode != 0:
        raise SystemExit(completed.returncode)


